package com.soundtriggers;

import net.runelite.api.HitsplatID;

/**
 * A user-facing grouping of RuneLite's many raw {@link HitsplatID} type codes
 * into the handful of categories a player actually cares about.
 *
 * <p>The "self vs. others" distinction is handled separately by
 * {@link HitsplatTarget}, so the {@code _ME}/{@code _OTHER} variants of an id
 * collapse into a single kind here, as do the various damage colour variants.
 */
public enum HitsplatKind
{
	ANY("Any"),
	DAMAGE("Damage",
		HitsplatID.DAMAGE_ME, HitsplatID.DAMAGE_OTHER,
		HitsplatID.DAMAGE_ME_CYAN, HitsplatID.DAMAGE_OTHER_CYAN,
		HitsplatID.DAMAGE_ME_ORANGE, HitsplatID.DAMAGE_OTHER_ORANGE,
		HitsplatID.DAMAGE_ME_YELLOW, HitsplatID.DAMAGE_OTHER_YELLOW,
		HitsplatID.DAMAGE_ME_WHITE, HitsplatID.DAMAGE_OTHER_WHITE,
		HitsplatID.DAMAGE_ME_POISE, HitsplatID.DAMAGE_OTHER_POISE,
		HitsplatID.DAMAGE_MAX_ME, HitsplatID.DAMAGE_MAX_ME_CYAN,
		HitsplatID.DAMAGE_MAX_ME_ORANGE, HitsplatID.DAMAGE_MAX_ME_YELLOW,
		HitsplatID.DAMAGE_MAX_ME_WHITE, HitsplatID.DAMAGE_MAX_ME_POISE),
	BLOCK("Block", HitsplatID.BLOCK_ME, HitsplatID.BLOCK_OTHER),
	HEAL("Heal", HitsplatID.HEAL),
	POISON("Poison", HitsplatID.POISON),
	VENOM("Venom", HitsplatID.VENOM),
	DISEASE("Disease", HitsplatID.DISEASE, HitsplatID.DISEASE_BLOCKED),
	BURN("Burn", HitsplatID.BURN),
	BLEED("Bleed", HitsplatID.BLEED),
	PRAYER_DRAIN("Prayer drain", HitsplatID.PRAYER_DRAIN);

	private final String displayName;
	private final int[] ids;

	HitsplatKind(String displayName, int... ids)
	{
		this.displayName = displayName;
		this.ids = ids;
	}

	/** Whether a raw {@link net.runelite.api.Hitsplat#getHitsplatType()} code falls under this kind. */
	boolean matches(int hitsplatType)
	{
		if (this == ANY)
		{
			return true;
		}
		for (int id : ids)
		{
			if (id == hitsplatType)
			{
				return true;
			}
		}
		return false;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.soundtriggers;

/**
 * Who <em>dealt</em> a hitsplat, as reported by {@link net.runelite.api.Hitsplat#isMine()}.
 * Independent of {@link HitsplatTarget}, which filters on <em>whom</em> the hitsplat lands.
 */
public enum HitsplatSource
{
	ANY("Any"),
	ME("Me"),
	OTHERS("Others");

	private final String displayName;

	HitsplatSource(String displayName)
	{
		this.displayName = displayName;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.soundtriggers;

public enum HitsplatTarget
{
	ANY("Any"),
	SELF("Self"),
	OTHERS("Others");

	private final String displayName;

	HitsplatTarget(String displayName)
	{
		this.displayName = displayName;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.soundtriggers;

/**
 * How a name filter is compared against an in-game name, for the
 * {@link TriggerType#PLAYER_SEEN} and {@link TriggerType#NPC_SEEN} triggers.
 */
public enum MatchMode
{
	/** The in-game name contains the filter (case-insensitive substring). */
	CONTAINS("Contains"),
	/** The in-game name equals the filter exactly (case-insensitive). */
	EXACT("Exact"),
        /** Any name will match the filter.*/
        ANY("Any");

	private final String displayName;

	MatchMode(String displayName)
	{
		this.displayName = displayName;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.soundtriggers;

/**
 * A player resource whose current value can be compared against a threshold.
 *
 * <p>All values are normalised to the same scale the player sees in-game:
 * health and prayer are absolute points, while run energy and special attack
 * are 0&ndash;100.
 */
public enum PlayerStat
{
	HEALTH("Health"),
	PRAYER("Prayer"),
	RUN_ENERGY("Run Energy"),
	SPECIAL_ATTACK("Special Attack");

	private final String displayName;

	PlayerStat(String displayName)
	{
		this.displayName = displayName;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.soundtriggers;

// Regions where sound triggers are disabled to prevent audio-based advantages.
// Mirrors the list maintained by RuneLite's Watchdog plugin; update this list
// when the development team announces changes in #development on their Discord.
enum RestrictedRegion
{
	ALCHEMICAL_HYDRA(5536),
	VARDORVIS(4405),
	LEVIATHAN(8291),
	WHISPERER(10595),
	SUCELLUS(12132),
	VORKATH(9023),
	INFERNO(9043),
	FIGHT_CAVE(9551),
	COLOSSEUM(7216),
	KALPHITE_QUEEN(13972),
	COX(13136, 13137, 13393, 13138, 13394, 13139, 13395, 13140, 13396, 13141, 13397, 13145, 13401, 12889),
	TOB(12613, 13125, 13122, 13123, 13379, 12612, 12611),
	TOA(14160, 15698, 15700, 14162, 14164, 15186, 15188, 14674, 14676, 15184, 15696),
	YAMA(6045),
	DOOM_OF_MOKHAIOTL(5269, 13668, 14180),
	NIGHTMARE(15515);

	private final int[] regionIds;

	RestrictedRegion(int... regionIds)
	{
		this.regionIds = regionIds;
	}

	static boolean isRestricted(int regionId)
	{
		for (RestrictedRegion r : values())
		{
			for (int id : r.regionIds)
			{
				if (id == regionId)
				{
					return true;
				}
			}
		}
		return false;
	}
}

