	/** Wall-clock time the trigger last fired, used to pace repeats. */
	final long lastFiredMs;

	StatTriggerState(boolean conditionMet, long lastFiredMs)
	{
		this.conditionMet = conditionMet;
		this.lastFiredMs = lastFiredMs;
	}
}

