	/**
	 * Wraps {@code onChange} in a {@link DocumentListener} that fires it on any
	 * insert, remove, or content change — the three callbacks Swing splits an
	 * edit into but which we always treat identically.
	 */
	private static DocumentListener simpleListener(Runnable onChange)
	{
		return new DocumentListener()
		{
			@Override public void insertUpdate(DocumentEvent e) { onChange.run(); }
			@Override public void removeUpdate(DocumentEvent e) { onChange.run(); }
			@Override public void changedUpdate(DocumentEvent e) { onChange.run(); }
		};
	}

	/**
	 * Binds a text field to a string setter: the trimmed text is passed through,
	 * with blank mapped to {@code null} ("match any"), and saved on every edit.
	 */
	private void bindNullableText(JTextField field, java.util.function.Consumer<String> setter)
	{
		field.getDocument().addDocumentListener(simpleListener(() ->
		{
			String text = field.getText().trim();
			setter.accept(text.isEmpty() ? null : text);
			plugin.saveTriggers();
		}));
	}

	/**
	 * Binds a text field to an integer setter: blank maps to {@code null}, a valid
	 * number is parsed and saved, and unparseable input is ignored so the user can
	 * finish typing without the partial value being persisted.
	 */
	private void bindNullableInt(JTextField field, java.util.function.Consumer<Integer> setter)
	{
		field.getDocument().addDocumentListener(simpleListener(() ->
		{
			String text = field.getText().trim();
			Integer value;
			if (text.isEmpty())
			{
				value = null;
			}
			else
			{
				try
				{
					value = Integer.parseInt(text);
				}
				catch (NumberFormatException ignored)
				{
					return;
				}
			}
			setter.accept(value);
			plugin.saveTriggers();
		}));
	}

	/**
	 * Like {@link #bindNullableInt} but also rejects zero and negative values,
	 * treating them as unparseable (the setter is not called and nothing is saved).
	 */
	private void bindPositiveInt(JTextField field, java.util.function.Consumer<Integer> setter)
	{
		field.getDocument().addDocumentListener(simpleListener(() ->
		{
			String text = field.getText().trim();
			Integer value;
			if (text.isEmpty())
			{
				value = null;
			}
			else
			{
				try
				{
					value = Integer.parseInt(text);
					if (value <= 0)
					{
						return;
					}
				}
				catch (NumberFormatException ignored)
				{
					return;
				}
			}
			setter.accept(value);
			plugin.saveTriggers();
		}));
	}

	private JComboBox<MatchMode> makeMatchModeBox(MatchMode current, java.util.function.Consumer<MatchMode> setter)
	{
		JComboBox<MatchMode> box = makeEnumCombo(MatchMode.values(), current, setter);
		box.setToolTipText("Any: match everything. Contains: match part of the name. Exact: match the whole name.");
		return box;
	}

	/**
	 * Builds a combo box over an enum's values, pre-selects {@code current}, and
	 * saves the chosen value through {@code setter} on every change.
	 */
	private <E> JComboBox<E> makeEnumCombo(E[] values, E current, java.util.function.Consumer<E> setter)
	{
		JComboBox<E> box = new JComboBox<>(values);
		box.setSelectedItem(current != null ? current : values[0]);
		box.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		box.setForeground(Color.WHITE);
		box.setFont(FontManager.getRunescapeSmallFont());
		box.setRenderer(COMBO_RENDERER);
		box.addActionListener(e ->
		{
			int index = box.getSelectedIndex();
			if (index >= 0)
			{
				setter.accept(box.getItemAt(index));
				plugin.saveTriggers();
			}
		});
		return box;
	}
}

package com.soundtriggers;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import lombok.extern.slf4j.Slf4j;

import java.util.ArrayList;
import java.util.List;

/**
 * Converts the trigger list to and from the JSON stored in RuneLite config.
 *
 * <p>Pure and free of {@code Client}/{@code ConfigManager}: strings in, triggers
 * out (and back). That keeps the parts most likely to break across plugin
 * versions — the schema-version envelope and the per-trigger fault isolation —
 * unit-testable without a live client. The plugin shell owns the actual
 * {@code ConfigManager} get/set and any recovery side effects.
 */
@Slf4j
final class TriggerStore
{
	/** Current on-disk schema version, written into every saved envelope. */
	static final int SCHEMA_VERSION = 1;

	private static final String KEY_VERSION = "version";
	private static final String KEY_TRIGGERS = "triggers";

	private TriggerStore()
	{
	}

	/** Serializes {@code triggers} into a versioned envelope JSON string. */
	static String serialize(Gson gson, List<SoundTrigger> triggers)
	{
		JsonObject root = new JsonObject();
		root.addProperty(KEY_VERSION, SCHEMA_VERSION);
		root.add(KEY_TRIGGERS, gson.toJsonTree(triggers));
		return gson.toJson(root);
	}

	/**
	 * Parses the stored config value (a {@code {"version":N,"triggers":[…]}}
	 * envelope) into a list of triggers. Each trigger is parsed in isolation: an
	 * element that fails to deserialize is skipped and logged, so one bad trigger
	 * can never take down the rest of the list.
	 *
	 * <p>A {@code null}/empty input, or a value that isn't a valid envelope,
	 * yields an empty list (the latter is logged).
	 */
	static List<SoundTrigger> parse(Gson gson, String json)
	{
		List<SoundTrigger> triggers = new ArrayList<>();
		if (json == null || json.isEmpty())
		{
			return triggers;
		}

		JsonArray array;
		try
		{
			array = new JsonParser().parse(json).getAsJsonObject().getAsJsonArray(KEY_TRIGGERS);
		}
		catch (Exception e)
		{
			log.error("Sound Triggers: stored triggers are not a valid envelope", e);
			return triggers;
		}

		if (array == null)
		{
			return triggers;
		}

		for (JsonElement element : array)
		{
			try
			{
				SoundTrigger trigger = gson.fromJson(element, SoundTrigger.class);
				if (trigger != null)
				{
					triggers.add(trigger);
				}
			}
			catch (Exception e)
			{
				log.warn("Sound Triggers: skipping unreadable trigger: {}", element, e);
			}
		}
		return triggers;
	}
}

package com.soundtriggers;

public enum TriggerType
{
	HITSPLAT("Hitsplat"),
	ITEM_DROP("Item Drop"),
	CHAT_MESSAGE("Chat Message"),
	NPC_SEEN("NPC Seen"),
